<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import{DatabaseZap}from'lucide-vue-next';import{api}from'../api/client';import PageHeader from'../components/PageHeader.vue';import ContentCard from'../components/ContentCard.vue';import FileDropzone from'../components/FileDropzone.vue';const file=ref<File|null>(null),loading=ref(false),result=ref<any>();async function migrate(){if(!file.value)return;const data=new FormData();data.append('file',file.value);loading.value=true;try{result.value=await api('/api/admin/migrate',{method:'POST',body:data});ElMessage.success('旧数据库迁移完成')}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}</script>
<template><PageHeader title="旧数据库迁移" description="将 Python 旧版本的授权库存和已分配关系安全导入新系统。"/><ContentCard title="上传旧版 auth_codes.db" description="迁移不会覆盖新数据库中已有的 PID + DID；冲突记录将跳过并报告。"><div class="migration-box"><FileDropzone accept=".db,.sqlite,.sqlite3" hint="请选择旧系统 data/auth_codes.db" @change="file=$event"/><el-alert title="迁移范围" description="仅导入授权库存、完整载荷、批次、状态、绑定 MAC 与分配时间；不迁移旧请求日志和白名单。" type="info" show-icon/><el-button type="primary" :icon="DatabaseZap" :disabled="!file" :loading="loading" @click="migrate">开始迁移</el-button><div v-if="result" class="migration-result"><strong>迁移完成</strong><span>读取 {{result.totalRows}} 条，成功 {{result.inserted}} 条，跳过 {{result.skipped}} 条。</span><el-alert v-if="result.conflicts?.length" title="冲突记录" :description="result.conflicts.join('、')" type="warning"/></div></div></ContentCard></template>
